188: static uint64_t buscar_fuente_demux(const uint64_t* gA, int x, int y, int z, int N) {
189:     // v26-SYM1: reducer simetrico para TODAS las fuentes direccionales que apuntan al destino.
190:     // - 0 fuentes: conserva el comportamiento nulo.
191:     // - 1 fuente: conserva EXACTAMENTE el raw de v25.
192:     // - >1 fuentes: suma s_reg con la misma cota P_KERNEL-1 ya usada por DEMUX,
193:     //   y compone la direccion mediante signo de la suma vectorial.
194:     // La reduccion es conmutativa y no depende del indice de MOORE_DXYZ.
195:     int count = 0;
196:     uint64_t only_source = 0;
197:     uint32_t sum_sreg = 0;
198:     int sum_dx = 0, sum_dy = 0, sum_dz = 0;
199: 
200:     for (int k = 0; k < 26; ++k) {
201:         int nx = wrap(x + MOORE_DXYZ[k][0], N);
202:         int ny = wrap(y + MOORE_DXYZ[k][1], N);
203:         int nz = wrap(z + MOORE_DXYZ[k][2], N);
204:         size_t nidx = idx3d(nx, ny, nz, N);
205:         uint64_t nv = gA[nidx];
206:         int ndx = get_dir_x(nv), ndy = get_dir_y(nv), ndz = get_dir_z(nv);
207:         if (ndx == 0 && ndy == 0 && ndz == 0) continue;
208:         if (wrap(nx + ndx, N) == x && wrap(ny + ndy, N) == y && wrap(nz + ndz, N) == z) {
209:             ++count;
210:             only_source = nv;
211:             sum_sreg += static_cast<uint32_t>(get_s_reg(nv));
212:             sum_dx += ndx;
213:             sum_dy += ndy;
214:             sum_dz += ndz;
215:         }
216:     }
217: 
218:     if (count == 0) return 0;
219:     if (count == 1) return only_source;
220: 
221:     const uint32_t cap = static_cast<uint32_t>(P_KERNEL - 1);
222:     if (sum_sreg > cap) sum_sreg = cap;
223:     const int out_dx = (sum_dx > 0) ? 1 : ((sum_dx < 0) ? -1 : 0);
224:     const int out_dy = (sum_dy > 0) ? 1 : ((sum_dy < 0) ? -1 : 0);
225:     const int out_dz = (sum_dz > 0) ? 1 : ((sum_dz < 0) ? -1 : 0);
226:     return pack_voxel(1, static_cast<uint16_t>(sum_sreg), out_dx, out_dy, out_dz, SEM_NORMAL);
